import React from 'react';
import {AbsoluteFill,interpolateColors} from 'remotion';
import {useS,T,en,DUR,Easing,interpolate,clamp,FONT,MANO,Destello,Ondas,golpe} from './kit';
// DINERO 2026-11-29_12 "El premio que te cobra" (Opus/animador 27-nov). 2.5D: Vol (luz y sombra), 3 capas con parallax,
// giro leve en perspectiva, sombra en el suelo, manos con volumen (caps). Protagonista: la caja de regalo roja con lazo dorado
// que por dentro esta vacia y solo tiene un anzuelo. Kevin: camiseta lima, gorra al reves.
export const SUBS={arriba:860,size:84,acento:'#FFC83D'};
const A=[0,8,33,49,68,92,115,135].map(T);
const P=(w:string,n=1)=>en(w,n)-.2; // el dibujo entra 0,2 s antes de su palabra
const c01=(x:number)=>Math.max(0,Math.min(1,x));
const q=(s:number,a:number,b:number)=>interpolate(s,[a,Math.max(a+.01,b)],[0,1],{...clamp,easing:Easing.inOut(Easing.cubic)});
const ob=(x:number)=>{const c1=1.70158,c3=c1+1,y=c01(x);return 1+c3*Math.pow(y-1,3)+c1*Math.pow(y-1,2);};
const pop=(s:number,t0:number,d=.4)=>ob((s-t0)/d);
const hsh=(j:number)=>{const x=Math.sin(j*127.1+311.7)*43758.5453;return x-Math.floor(x);};
const ell=(cx:number,cy:number,rx:number,ry:number)=>`M${cx-rx} ${cy}a${rx} ${ry} 0 1 0 ${2*rx} 0a${rx} ${ry} 0 1 0 ${-2*rx} 0Z`;
const rr=(x:number,y:number,w:number,h:number,r:number)=>`M${x+r} ${y}H${x+w-r}A${r} ${r} 0 0 1 ${x+w} ${y+r}V${y+h-r}A${r} ${r} 0 0 1 ${x+w-r} ${y+h}H${x+r}A${r} ${r} 0 0 1 ${x} ${y+h-r}V${y+r}A${r} ${r} 0 0 1 ${x+r} ${y}Z`;
const caps=(x1:number,y1:number,x2:number,y2:number,w:number)=>{const a=Math.atan2(y2-y1,x2-x1),r=w/2,nx=-Math.sin(a)*r,ny=Math.cos(a)*r;
 return `M${x1+nx} ${y1+ny}L${x2+nx} ${y2+ny}A${r} ${r} 0 0 0 ${x2-nx} ${y2-ny}L${x1-nx} ${y1-ny}A${r} ${r} 0 0 0 ${x1+nx} ${y1+ny}Z`;};
const star=(n:number,r1:number,r2:number)=>Array.from({length:n*2}).map((_,j)=>{const a=Math.PI*j/n-Math.PI/2,r=j%2?r2:r1;return `${j?'L':'M'}${Math.cos(a)*r} ${Math.sin(a)*r}`;}).join('')+'Z';
type C3=[string,string,string];
const SKIN:C3=['#ffe3c4','#eeaa7c','#a05a38'],HAIR:C3=['#b0825c','#5a3620','#1e0f06'];
const RED:C3=['#ff93a8','#FF3355','#8a0a2a'],GOLD:C3=['#fff3b8','#FFC83D','#a86a00'],LIME:C3=['#e2ffc8','#7CFF4F','#2a8a1a'];
const CAP:C3=['#ffc890','#ff8a2a','#a8400a'],METAL:C3=['#ffffff','#b8c4d4','#5a6a80'],DARK:C3=['#6a7088','#262c3e','#0a0c16'];
const CONF=['#FF3355','#FFC83D','#22D37A','#25C7FF','#B84DFF','#FF8A2A','#ffffff'];
// Volumen: color medio, sombra suave abajo-derecha, luz suave arriba-izquierda y borde fino.
const Vol:React.FC<{id:string;d:string;c:C3;sw?:number;o?:number;borde?:string}>=({id,d,c,sw=70,o=24,borde})=><g>
 <defs><clipPath id={id}><path d={d}/></clipPath></defs>
 <path d={d} fill={c[1]}/>
 <g clipPath={`url(#${id})`}>
  <path d={d} fill='none' stroke={c[2]} strokeWidth={sw} filter='url(#b18)' transform={`translate(${-o} ${-o})`}/>
  <path d={d} fill='none' stroke={c[0]} strokeWidth={sw*.75} filter='url(#b18)' transform={`translate(${o} ${o})`}/>
 </g>
 <path d={d} fill='none' stroke={borde||c[2]} strokeWidth={3} opacity={.55}/>
</g>;
const Brillo2:React.FC<{x:number;y:number;rx:number;ry:number;r?:number;o?:number}>=({x,y,rx,ry,r=-30,o=.75})=><ellipse cx={x} cy={y} rx={rx} ry={ry} transform={`rotate(${r} ${x} ${y})`} fill='#fff' opacity={o} filter='url(#b6)'/>;
const Defs:React.FC=()=><defs>
 <filter id='b6' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='6'/></filter>
 <filter id='b18' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='18'/></filter>
 <filter id='b40' x='-50%' y='-50%' width='200%' height='200%'><feGaussianBlur stdDeviation='40'/></filter>
 <radialGradient id='luz'><stop stopColor='#ffffff' stopOpacity='.55'/><stop offset='1' stopColor='#ffffff' stopOpacity='0'/></radialGradient>
 <radialGradient id='hueco' cx='.5' cy='.4'><stop stopColor='#5a0a22'/><stop offset='1' stopColor='#12000a'/></radialGradient>
 <linearGradient id='scr' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#7a4dff'/><stop offset='.55' stopColor='#2f5bff'/><stop offset='1' stopColor='#00c2ff'/></linearGradient>
 <linearGradient id='scr2' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#ff5fa8'/><stop offset='.5' stopColor='#ffb020'/><stop offset='1' stopColor='#25c7ff'/></linearGradient>
 <radialGradient id='glass' cx='.38' cy='.32' r='.75'><stop stopColor='#ffffff' stopOpacity='.5'/><stop offset='.55' stopColor='#bfe6ff' stopOpacity='.12'/><stop offset='1' stopColor='#6aa8ff' stopOpacity='.4'/></radialGradient>
 <linearGradient id='tabla' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#2fae6a'/><stop offset='.6' stopColor='#1b8a52'/><stop offset='1' stopColor='#0d5a34'/></linearGradient>
 <linearGradient id='cielo' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#7fc4ff'/><stop offset='1' stopColor='#ffe9b8'/></linearGradient>
 <linearGradient id='haz' x1='0' y1='0' x2='1' y2='1'><stop stopColor='#ffb347' stopOpacity='.75'/><stop offset='1' stopColor='#ffb347' stopOpacity='0'/></linearGradient>
 <linearGradient id='rayo' x1='0' y1='0' x2='0' y2='1'><stop stopColor='#fff3b8' stopOpacity='.9'/><stop offset='1' stopColor='#ffc83d' stopOpacity='0'/></linearGradient>
</defs>;
const Txt:React.FC<{x:number;y:number;size:number;fill?:string;stroke?:string;sw?:number;font?:string;w?:number;anchor?:'start'|'middle'|'end';rot?:number;o?:number;tl?:number;children:React.ReactNode}>=({x,y,size,fill='#fff',stroke,sw=0,font=FONT,w=900,anchor='middle',rot=0,o=1,tl,children})=>
 <text x={x} y={y} fontSize={size} fontWeight={w} fontFamily={font} fill={fill} stroke={stroke} strokeWidth={sw} paintOrder='stroke' strokeLinejoin='round' textAnchor={anchor} opacity={o} textLength={tl} lengthAdjust={tl?'spacingAndGlyphs':undefined} transform={rot?`rotate(${rot} ${x} ${y})`:undefined}>{children}</text>;
const Spark:React.FC<{x:number;y:number;k?:number;r?:number;o?:number;c?:string}>=({x,y,k=1,r=0,o=1,c='#fff'})=><g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`} opacity={o}><path d='M0 -30L6 -6L30 0L6 6L0 30L-6 6L-30 0L-6 -6Z' fill={c}/><circle r={5} fill='#fff'/></g>;
// ---------- Mano con volumen: palma, 4 dedos y pulgar como capsulas cerradas, nudillos y unas. Origen en la muneca, apunta arriba.
const FING:[number,number,number][]=[[-39,62,-12],[-13,76,-3],[13,70,5],[39,54,13]];
const Hand:React.FC<{id:string;x:number;y:number;r?:number;k?:number;c?:C3;curl?:number;th?:number;mir?:boolean;ang?:number[]}>=({id,x,y,r=0,k=1,c=SKIN,curl=0,th=-50,mir=false,ang})=>{
 const dark=c[1]==='#16060a';
 return <g transform={`translate(${x} ${y}) rotate(${r}) scale(${mir?-k:k} ${k})`}>
 {FING.map(([fx,L,an0],j)=>{const an=(ang?ang[j]:an0)*Math.PI/180,len=L*(1-.5*curl),bx=fx,by=-120,tx=bx+Math.sin(an)*len,ty=by-Math.cos(an)*len;
  return <g key={j}><Vol id={id+'f'+j} d={caps(bx,by,tx,ty,25)} c={c} sw={16} o={5}/>
  {!dark&&curl<.6&&<ellipse cx={tx-Math.sin(an)*7} cy={ty+Math.cos(an)*7} rx={8} ry={10} transform={`rotate(${an*57} ${tx} ${ty})`} fill='#ffe0d6' stroke={c[2]} strokeWidth={2}/>}</g>;})}
 <Vol id={id+'p'} d='M-52 6C-62 -50 -60 -95 -52 -138C-20 -150 20 -150 52 -138C60 -95 62 -50 52 6C30 26 -30 26 -52 6Z' c={c} sw={50} o={14}/>
 {!dark&&[-39,-13,13,39].map((fx,j)=><ellipse key={j} cx={fx} cy={-128} rx={11} ry={7} fill={c[2]} opacity={.25}/>)}
 {!dark&&<path d='M-30 -60Q0 -48 30 -60' stroke={c[2]} strokeWidth={4} fill='none' opacity={.35}/>}
 {(()=>{const t=th*Math.PI/180,L=74*(1-.3*curl),bx=-44,by=-22,tx=bx+Math.sin(t)*L,ty=by-Math.cos(t)*L;
  return <g><Vol id={id+'t'} d={caps(bx,by,tx,ty,30)} c={c} sw={18} o={5}/>{!dark&&<ellipse cx={tx-Math.sin(t)*7} cy={ty+Math.cos(t)*7} rx={9} ry={11} transform={`rotate(${th} ${tx} ${ty})`} fill='#ffe0d6' stroke={c[2]} strokeWidth={2}/>}</g>;})()}
 </g>;};
// Pulgar arriba con volumen: puno con cuatro dedos enrollados y el pulgar levantado.
const Pulgar:React.FC<{id:string;x:number;y:number;k?:number;r?:number}>=({id,x,y,k=1,r=0})=><g transform={`translate(${x} ${y}) rotate(${r}) scale(${k})`}>
 <Vol id={id+'m'} d={caps(40,120,70,300,150)} c={LIME} sw={50} o={14}/>
 <Vol id={id+'p'} d='M-110 -50C-120 -130 -70 -160 -10 -160L90 -160C140 -150 150 -90 140 -30C132 60 80 110 20 118L-60 118C-110 100 -110 40 -110 -50Z' c={SKIN} sw={60} o={18}/>
 {[-100,-44,12,68].map((yy,j)=><g key={j}><Vol id={id+'d'+j} d={caps(-10,yy,112,yy+6,54)} c={SKIN} sw={22} o={6}/><path d={`M96 ${yy-16}Q112 ${yy+6} 96 ${yy+26}`} stroke={SKIN[2]} strokeWidth={3} fill='none' opacity={.5}/></g>)}
 <Vol id={id+'t'} d={caps(-62,-90,-72,-300,68)} c={SKIN} sw={30} o={8}/>
 <ellipse cx={-72} cy={-290} rx={24} ry={28} fill='#ffe0d6' stroke={SKIN[2]} strokeWidth={3}/><Brillo2 x={-80} y={-298} rx={8} ry={12} r={10} o={.8}/>
 <path d='M-98 -130Q-72 -140 -44 -130' stroke={SKIN[2]} strokeWidth={4} fill='none' opacity={.4}/>
 <Brillo2 x={-70} y={-110} rx={16} ry={40} r={10} o={.45}/>
</g>;
// ---------- Kevin: 22 anos, piel clara bronceada, pelo castano despeinado, camiseta lima, gorra al reves. Origen = centro de la cabeza.
const Kevin:React.FC<{id:string;s:number;mood?:'feliz'|'sonrisa'|'duda'|'ceja';mira?:[number,number];bl?:number;br?:number;chispa?:boolean;torso?:boolean;arms?:boolean}>=({id,s,mood='feliz',mira=[0,0],bl=0,br=0,chispa=false,torso=true,arms=false})=>{
 const blink=(s%3.4)<.13?.12:1,sw=Math.sin(s*9);
 const mouth=mood==='feliz'?<g><path d='M-82 112Q0 130 82 112Q72 218 0 224Q-72 218 -82 112Z' fill='#5a0f1c' stroke='#b04050' strokeWidth={5}/><path d='M-72 117Q0 134 72 117L68 142Q0 156 -68 142Z' fill='#fff'/><ellipse cx={0} cy={196} rx={40} ry={20} fill='#ff7a8a'/></g>
  :mood==='sonrisa'?<g><path d='M-76 126Q0 200 76 126Q0 150 -76 126Z' fill='#d9607a' stroke='#9a3048' strokeWidth={4}/><path d='M-60 134Q0 176 60 134Q0 146 -60 134Z' fill='#fff'/><path d='M-90 112Q-96 130 -80 142M90 112Q96 130 80 142' stroke={SKIN[2]} strokeWidth={5} fill='none' opacity={.6}/></g>
  :mood==='duda'?<g><path d='M-40 158Q0 146 46 164' stroke='#9a3048' strokeWidth={11} fill='none' strokeLinecap='round'/><path d='M-30 168Q6 174 40 172' stroke='#e0707a' strokeWidth={5} fill='none' opacity={.7} strokeLinecap='round'/></g>
  :<g><path d='M-62 154Q10 168 76 118' stroke='#9a3048' strokeWidth={11} fill='none' strokeLinecap='round'/><path d='M82 112Q96 124 86 140' stroke={SKIN[2]} strokeWidth={5} fill='none' opacity={.7}/></g>;
 return <g>
 {torso&&<>
  <Vol id={id+'n'} d='M-62 170L-72 310L72 310L62 170Z' c={SKIN} sw={40} o={12}/>
  <Vol id={id+'t'} d='M-290 700C-282 440 -200 320 -72 280L0 335L72 280C200 320 282 440 290 700Z' c={LIME} sw={130} o={36}/>
  <path d='M-76 284Q0 350 76 284' stroke={LIME[2]} strokeWidth={12} fill='none' opacity={.6}/><path d='M-150 420Q-100 470 -130 560M150 420Q110 480 140 580' stroke={LIME[2]} strokeWidth={6} fill='none' opacity={.35}/>
  <Brillo2 x={-150} y={430} rx={26} ry={90} r={18} o={.35}/>
 </>}
 {arms&&[-1,1].map(m=>{const wx=m*(335+sw*14),wy=34;return <g key={m}>
  <Vol id={id+'ua'+m} d={caps(m*205,390,m*300,225,108)} c={LIME} sw={50} o={14}/>
  <Vol id={id+'fa'+m} d={caps(m*300,225,wx,wy+14,66)} c={SKIN} sw={30} o={9}/>
  <Hand id={id+'h'+m} x={wx} y={wy+16} r={m*(12+sw*10)} k={.95} mir={m<0} th={-58}/>
 </g>;})}
 {[-1,1].map(m=><Vol key={m} id={id+'e'+m} d={ell(m*182,12,34,54)} c={SKIN} sw={26} o={8}/>)}
 <Vol id={id+'h'} d='M0 -250C120 -250 185 -150 182 -20C180 110 110 215 0 232C-110 215 -180 110 -182 -20C-185 -150 -120 -250 0 -250Z' c={SKIN} sw={130} o={36}/>
 {[-1,1].map(m=><ellipse key={m} cx={m*98} cy={78} rx={46} ry={28} fill='#ff7a6a' opacity={.3} filter='url(#b18)'/>)}
 <Vol id={id+'fr'} d='M-188 -62C-205 -130 -172 -158 -118 -152C-60 -122 40 -132 110 -148C172 -142 204 -112 192 -60C172 -104 150 -92 130 -82C110 -124 80 -92 50 -86C20 -112 -10 -82 -40 -90C-70 -124 -100 -82 -130 -94C-152 -88 -170 -82 -188 -62Z' c={HAIR} sw={40} o={12}/>
 {[-1,1].map(m=><Vol key={m} id={id+'sp'+m} d={`M${m*190} -112L${m*236} -156L${m*212} -98L${m*246} -72L${m*194} -66Z`} c={HAIR} sw={20} o={6}/>)}
 <Vol id={id+'cp'} d='M-194 -116C-208 -254 -106 -326 0 -326C106 -326 208 -254 194 -116C130 -164 -130 -164 -194 -116Z' c={CAP} sw={90} o={28}/>
 <path d='M0 -324C-44 -270 -44 -196 -12 -156M0 -324C46 -270 52 -196 16 -156' stroke={CAP[2]} strokeWidth={4} fill='none' opacity={.6}/><circle cx={0} cy={-326} r={12} fill={CAP[0]} stroke={CAP[2]} strokeWidth={3}/>
 <Brillo2 x={-95} y={-250} rx={60} ry={20} r={-28} o={.55}/>
 <Vol id={id+'st'} d='M-64 -158Q0 -138 64 -158L64 -132Q0 -112 -64 -132Z' c={['#e0e4ee','#9aa4b8','#4a5468']} sw={14} o={4}/>{[-30,0,30].map(xx=><circle key={xx} cx={xx} cy={-138} r={4} fill='#2a3040'/>)}
 {[-1,1].map(m=>{const b=m<0?bl:br;return <g key={m} transform={`translate(${m*74} -22)`}>
  <defs><clipPath id={id+'ec'+m}><path d='M-44 0Q0 -34 44 0Q0 32 -44 0Z'/></clipPath></defs>
  <g transform={`scale(1 ${blink})`}>
   <path d='M-44 0Q0 -34 44 0Q0 32 -44 0Z' fill='#fff'/>
   <g clipPath={`url(#${id}ec${m})`}><g transform={`translate(${mira[0]*9} ${mira[1]*7})`}>
    <circle r={22} fill='#7a4a20'/><circle r={22} fill='none' stroke='#3a1a08' strokeWidth={3}/><circle r={12} fill='#0a0a0a'/>
    <circle cx={7} cy={-8} r={7} fill='#fff'/>{chispa&&<><circle cx={-8} cy={8} r={3.4} fill='#fff'/><Spark x={9} y={-9} k={.5} r={s*60}/></>}
   </g></g>
   <path d='M-46 -1Q0 -38 46 -1' stroke='#2a160c' strokeWidth={6} fill='none'/>
  </g>
  <path d={`M${-m*48} ${-52+b+(mood==='duda'?m*-6:0)}Q0 ${-76+b} ${m*50} ${-54+b+(mood==='duda'?m*8:0)}`} stroke='#2a160c' strokeWidth={13} fill='none' strokeLinecap='round'/>
 </g>;})}
 <path d='M-14 -18C-20 25 -48 55 -42 78C-30 98 -12 92 0 98C12 92 30 98 42 78C48 55 20 25 14 -18' fill={SKIN[1]} stroke={SKIN[2]} strokeWidth={3}/><path d='M6 -8C10 30 26 55 30 72' stroke={SKIN[0]} strokeWidth={6} fill='none' opacity={.8} strokeLinecap='round'/>
 {[-1,1].map(m=><ellipse key={m} cx={m*17} cy={86} rx={9} ry={5} fill='#5a2a1a'/>)}
 {mouth}
 </g>;};
// ---------- Confeti
const Caida:React.FC<{s:number;n?:number;seed?:number;t0?:number}>=({s,n=40,seed=0,t0=0})=><g>{Array.from({length:n}).map((_,j)=>{
 const x0=hsh(j+seed)*1400-160,sp=240+hsh(j*3+seed)*280,y=((s-t0)*sp+hsh(j*7+seed)*2300)%2400-200,col=CONF[(j+seed)%CONF.length];
 return <g key={j} transform={`translate(${x0+Math.sin(s*2.4+j)*46} ${y}) rotate(${(s*170+j*47)%360}) scale(1 ${.25+.75*Math.abs(Math.cos(s*4+j))})`}><rect x={-10} y={-16} width={20} height={32} rx={3} fill={col}/><rect x={-10} y={-16} width={20} height={14} rx={3} fill='#fff' opacity={.3}/></g>;})}</g>;
const Estalla:React.FC<{s:number;x:number;y:number;t0:number;n?:number;V?:number}>=({s,x,y,t0,n=46,V=1})=>{const u=s-t0;if(u<0||u>3)return null;
 return <g>{Array.from({length:n}).map((_,j)=>{const a=hsh(j+1)*Math.PI*2,v=(380+hsh(j+9)*820)*V,px=x+Math.cos(a)*v*u*(1-u*.12),py=y+Math.sin(a)*v*u+520*u*u;
 return <g key={j} transform={`translate(${px} ${py}) rotate(${(u*(300+j*20))%360}) scale(1 ${.3+.7*Math.abs(Math.cos(u*9+j))})`} opacity={c01(1.6-u*.55)}><rect x={-11} y={-17} width={22} height={34} rx={3} fill={CONF[j%CONF.length]}/><rect x={-11} y={-17} width={22} height={14} rx={3} fill='#fff' opacity={.3}/></g>;})}</g>;};
// ---------- Caja de regalo (protagonista): roja brillante, lazo dorado; abierta esta vacia y tiene un anzuelo.
const Anzuelo:React.FC<{s:number}>=({s})=><g transform={`rotate(${Math.sin(s*2.6)*5} 0 -760)`}>
 <path d='M0 -760V-190' stroke='#e8f4ff' strokeWidth={3} opacity={.7}/>
 <path d='M0 -190V-112C0 -60 -62 -62 -62 -108' fill='none' stroke='#4a5a70' strokeWidth={20} strokeLinecap='round'/>
 <path d='M0 -190V-112C0 -60 -62 -62 -62 -108' fill='none' stroke='#cfe0f0' strokeWidth={14} strokeLinecap='round'/>
 <path d='M-3 -186V-114' fill='none' stroke='#fff' strokeWidth={4} strokeLinecap='round'/><path d='M-62 -108L-78 -128L-52 -126Z' fill='#e8f4ff' stroke='#4a5a70' strokeWidth={3}/>
 <circle cx={0} cy={-196} r={12} fill='none' stroke='#cfe0f0' strokeWidth={6}/>
 <Spark x={-6} y={-150+Math.sin(s*4)*10} k={.9+.4*Math.sin(s*7)} r={s*50}/>
</g>;
const Gift:React.FC<{id:string;x:number;y:number;k?:number;a?:number;lid?:number;op?:number;s:number;hook?:boolean;sombra?:boolean}>=({id,x,y,k=1,a=0,lid=0,op=1,s,hook=false,sombra=true})=>{
 const sx=Math.max(.22,Math.abs(Math.cos(a))),lf=c01(lid);
 return <g transform={`translate(${x} ${y}) scale(${k*sx} ${k})`} opacity={op}>
 {sombra&&<ellipse cy={196} rx={220} ry={38} fill='#000' opacity={.38} filter='url(#b18)'/>}
 {lf>0&&<ellipse cy={-50} rx={150} ry={36} fill='url(#hueco)' stroke='#8a0a2a' strokeWidth={5}/>}
 {hook&&lf>0&&<Anzuelo s={s}/>}
 <Vol id={id+'b'} d='M-150 -20H150V172Q0 198 -150 172Z' c={RED} sw={90} o={26}/>
 <Vol id={id+'r'} d='M-26 -20H26V186Q0 192 -26 186Z' c={GOLD} sw={26} o={8}/>
 <Brillo2 x={-100} y={50} rx={14} ry={60} r={8} o={.6}/>
 <g transform={`translate(${lf*250} ${-lf*330}) rotate(${lf*58} 0 -56)`} opacity={1-c01((lf-.75)/.25)}>
  <Vol id={id+'l'} d='M-172 -94H172V-20H-172Z' c={RED} sw={50} o={14}/>
